import sys

def can_form_matrix(matrix, n):
    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 1:
                if i > 0 and matrix[i-1][j] == 1:
                    return False
                if j > 0 and matrix[i][j-1] == 1:
                    return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        index += 1
        matrix = []
        for _ in range(n):
            row = list(map(int, list(input[index])))
            matrix.append(row)
            index += 1
        if can_form_matrix(matrix, n):
            results.append("YES")
        else:
            results.append("NO")
    for result in results:
        print(result)

main()
